"""Small PNG assets for DOCX export (contact icons, initials avatar), drawn with Pillow.

Contact and meta icons are embedded as PNG images, recoloured from the same SVG shapes the HTML templates
use (pre-rendered alpha masks in app/assets/icons), so the document looks the same on any computer.
"""
import io
import os
from functools import lru_cache

from PIL import Image, ImageDraw, ImageFont

from .fonts import font_file

ICON_DIR = os.path.join(os.path.dirname(__file__), "assets", "icons")
ICON_FONTS = ("SegoeIcons.ttf", "segmdl2.ttf")
BOLD_FONTS = ("segoeuib.ttf", "arialbd.ttf")
GLYPHS = {"email": "\ue715", "phone": "\ue717", "location": "\ue707", "web": "\ue774",
          "github": "\ue71b", "calendar": "\ue787"}
SS = 4  # supersampling factor for smooth edges


def _font(names, size):
    for name in names:
        path, index = font_file(name)
        if os.path.exists(path):
            return ImageFont.truetype(path, size, index=index)
    return ImageFont.load_default(size)


def _png(img: Image.Image, px: int) -> bytes:
    buf = io.BytesIO()
    img.resize((px, px), Image.LANCZOS).save(buf, "PNG", optimize=True)
    return buf.getvalue()


@lru_cache(maxsize=128)
def icon_png(kind: str, rgb: tuple[int, int, int], px: int = 48) -> bytes:
    """Square transparent PNG of a contact/meta icon in the given colour.

    Uses the same SVG shapes as the HTML templates (pre-rendered alpha masks in app/assets/icons),
    falling back to Segoe icon-font glyphs if a mask is missing.
    """
    mask_path = os.path.join(ICON_DIR, f"{kind if kind in GLYPHS or kind == 'linkedin' else 'web'}.png")
    if os.path.exists(mask_path):
        with Image.open(mask_path) as mask:
            alpha = mask.convert("RGBA").getchannel("A")
        img = Image.new("RGBA", alpha.size, (*rgb, 255))
        img.putalpha(alpha)
        buf = io.BytesIO()
        img.resize((px, px), Image.LANCZOS).save(buf, "PNG", optimize=True)
        return buf.getvalue()
    size = px * SS
    img = Image.new("RGBA", (size, size), (0, 0, 0, 0))
    draw = ImageDraw.Draw(img)
    if kind == "linkedin":
        pad = size * 0.06
        draw.rounded_rectangle((pad, pad, size - pad, size - pad), radius=size * 0.16, fill=(*rgb, 255))
        font = _font(BOLD_FONTS, int(size * 0.62))
        draw.text((size * 0.53, size * 0.55), "in", font=font, fill=(255, 255, 255, 255), anchor="mm")
    else:
        font = _font(ICON_FONTS, int(size * 0.9))
        draw.text((size / 2, size / 2), GLYPHS.get(kind, GLYPHS["web"]), font=font, fill=(*rgb, 255), anchor="mm")
    return _png(img, px)


@lru_cache(maxsize=32)
def avatar_png(initials: str, bg: tuple[int, int, int], fg: tuple[int, int, int],
               ring: tuple[int, int, int, int] | None = None, px: int = 360) -> bytes:
    """Circular initials badge (like the HTML template's avatar)."""
    size = px * SS
    img = Image.new("RGBA", (size, size), (0, 0, 0, 0))
    draw = ImageDraw.Draw(img)
    if ring:
        draw.ellipse((0, 0, size, size), fill=ring)
        inset = size * 0.075
        draw.ellipse((inset, inset, size - inset, size - inset), fill=(*bg, 255))
    else:
        draw.ellipse((0, 0, size, size), fill=(*bg, 255))
    font = _font(BOLD_FONTS, int(size * 0.36))
    draw.text((size / 2, size / 2), initials, font=font, fill=(*fg, 255), anchor="mm")
    return _png(img, px)
